-- 1. Drop existing tables (Optional, safe reset)
DROP TABLE IF EXISTS penilaian CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS kriteria CASCADE;
DROP TABLE IF EXISTS karyawan CASCADE;

-- 2. Create Tables with PostgreSQL syntax

CREATE TABLE karyawan (
    id SERIAL PRIMARY KEY,
    nik VARCHAR(20) UNIQUE NOT NULL,
    nama VARCHAR(100) NOT NULL,
    jabatan VARCHAR(100) NOT NULL,
    divisi VARCHAR(100) NOT NULL,
    role VARCHAR(20) DEFAULT 'karyawan' NOT NULL
);

CREATE TABLE kriteria (
    id SERIAL PRIMARY KEY,
    kode VARCHAR(10) UNIQUE NOT NULL,
    nama VARCHAR(100) NOT NULL,
    tipe VARCHAR(10) NOT NULL,
    bobot DOUBLE PRECISION NOT NULL
);

CREATE TABLE penilaian (
    id SERIAL PRIMARY KEY,
    karyawan_id INTEGER NOT NULL REFERENCES karyawan(id) ON DELETE CASCADE,
    kriteria_id INTEGER NOT NULL REFERENCES kriteria(id) ON DELETE CASCADE,
    nilai DOUBLE PRECISION DEFAULT 0.0 NOT NULL
);

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(20) DEFAULT 'karyawan' NOT NULL,
    must_change_password BOOLEAN DEFAULT TRUE,
    karyawan_id INTEGER REFERENCES karyawan(id) ON DELETE CASCADE
);


